function survivors(rocks: number[]): number[] {
  const arr = [...rocks];
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i + 1 < arr.length; i++) {
      if (arr[i] > 0 && arr[i + 1] < 0) {
        const a = arr[i], b = -arr[i + 1];
        if (a > b) arr.splice(i + 1, 1);
        else if (a < b) arr.splice(i, 1);
        else arr.splice(i, 2);
        changed = true;
        break;
      }
    }
  }
  return arr;
}

