function survivors(rocks: number[]): number[] {
  const st: number[] = [];
  for (const x of rocks) {
    let alive = true;
    while (alive && x < 0 && st.length && st[st.length - 1] > 0) {
      const top = st[st.length - 1];
      if (top < -x) st.pop();
      else {
        if (top === -x) st.pop();
        alive = false;
      }
    }
    if (alive) st.push(x);
  }
  return st;
}

